diagnostic_evidence.quote:
For every compact $K\Subset\Omega_R$,
\begin{equation}\label{eq:field-convergence}
  \|u-u_\sigma^c\|_{H^1(K)}
  \le C_K\left(\mathcal P(\bar\sigma)e^{-c\bar\sigma}
    +\mathcal P(\bar\sigma)e^{-Z(L_2+d_2)}\right)
  \|g\|_{Y_R'} .
\end{equation}

Consequently, for every compact $K\Subset\Omega_p$,
\begin{equation}
  \|u-u_\sigma^{\rm ex}\|_{H^1(K)}
  \le C_K\mathcal P(\bar\sigma)\left(e^{-c_0k\bar\sigma}+e^{-Z(L_2+d_2)}\right)\|g\|_{Y_R'}.
\end{equation}

failure_location.quote:
for every compact $K\Subset\Omega_R$,
\begin{equation}\label{eq:nearest-image-total-field-error}
  \|u-u_\sigma^{\rm ni}\|_{H^1(K)}
  \le C_K\left(\mathcal P(\bar\sigma)e^{-c_{\rm ni}\bar\sigma}
       +\mathcal P(\bar\sigma)e^{-Z(L_2+d_2)}\right)\|g\|_{Y_R'} .
\end{equation}
